/**
 * Unit III: Client-Side Form Validation Support
 * Automatically validates data-val rules (data-val-required, data-val-range, data-val-length, data-val-regex, data-val-email)
 * generated by ASP.NET Core Tag Helpers before submitting to server.
 */
document.addEventListener("DOMContentLoaded", function () {
    const forms = document.querySelectorAll("form[data-val-validate='true'], form");

    forms.forEach(form => {
        form.addEventListener("submit", function (e) {
            let isValid = true;
            const inputs = form.querySelectorAll("[data-val='true']");

            inputs.forEach(input => {
                const errorSpan = form.querySelector(`[data-valmsg-for='${input.name}']`);
                let errorMsg = null;
                const val = input.value.trim();

                // Required check
                if (input.hasAttribute("data-val-required") && val === "") {
                    errorMsg = input.getAttribute("data-val-required");
                }
                // Range check
                else if (input.hasAttribute("data-val-range") && val !== "") {
                    const num = parseFloat(val);
                    const min = parseFloat(input.getAttribute("data-val-range-min") || "0");
                    const max = parseFloat(input.getAttribute("data-val-range-max") || "100");
                    if (isNaN(num) || num < min || num > max) {
                        errorMsg = input.getAttribute("data-val-range");
                    }
                }
                // Length check
                else if (input.hasAttribute("data-val-length") && val !== "") {
                    const maxLen = parseInt(input.getAttribute("data-val-length-max") || "9999");
                    const minLen = parseInt(input.getAttribute("data-val-length-min") || "0");
                    if (val.length < minLen || val.length > maxLen) {
                        errorMsg = input.getAttribute("data-val-length");
                    }
                }
                // Regex check
                else if (input.hasAttribute("data-val-regex") && val !== "") {
                    const pattern = new RegExp(input.getAttribute("data-val-regex-pattern"));
                    if (!pattern.test(val)) {
                        errorMsg = input.getAttribute("data-val-regex");
                    }
                }

                if (errorMsg && errorSpan) {
                    errorSpan.textContent = errorMsg;
                    errorSpan.className = "text-danger field-validation-error";
                    input.classList.add("is-invalid");
                    isValid = false;
                } else if (errorSpan) {
                    errorSpan.textContent = "";
                    errorSpan.className = "field-validation-valid";
                    input.classList.remove("is-invalid");
                    input.classList.add("is-valid");
                }
            });

            if (!isValid) {
                e.preventDefault();
                const summary = form.querySelector("[asp-validation-summary], .validation-summary-valid, .validation-summary-errors");
                if (summary) {
                    summary.className = "alert alert-danger validation-summary-errors";
                    summary.innerHTML = "<strong>Please correct the validation errors marked in red below.</strong>";
                }
            }
        });

        // Realtime clear on input
        form.querySelectorAll("[data-val='true']").forEach(input => {
            input.addEventListener("input", function () {
                const errorSpan = form.querySelector(`[data-valmsg-for='${input.name}']`);
                if (errorSpan && errorSpan.textContent) {
                    errorSpan.textContent = "";
                    input.classList.remove("is-invalid");
                }
            });
        });
    });
});
